(function(g){const policy={"version": "arraba-2026-v1", "text": "تصريح وإقرار بالمشاركة في السباق\n\nأصرّح بموجب هذا بأن جميع التفاصيل التي قدّمتها صحيحة، وأن حالتي الصحية والجسدية والنفسية قد خضعت للفحص والموافقة من قِبل طبيب مختص قبل مشاركتي في السباق، ولم يتم العثور على أي أمر غير طبيعي.\n\nأعلم أن اللجنة المنظمة للحدث، والجهة المستضيفة، والجهة المنظمة، والمنظّم الفعلي، والجهات الراعية، لن تتحمل أي مسؤولية عن أي ضرر قد يلحق بي، بما في ذلك الأضرار الجسدية التي قد أتعرض لها قبل الحدث أو أثناءه أو بعده، وكذلك عن فقدان أي من المعدات أو الأغراض الشخصية.", "sizes": ["14", "16", "18", "S", "M", "L", "XL", "2XL"]};if(typeof module!=="undefined"&&module.exports)module.exports=policy;else g.StudentPolicy=policy;})(globalThis);
